import { describe, expect, test } from "bun:test";
import { readFileSync } from "node:fs";
import { join } from "node:path";
import { createModel, formatElapsed, ingestLive, renderSwarmBar, renderSwarmBarFrame, statusText, type SwarmBarModel, visibleRuns } from "../src/swarm_bar.ts";
import { REPO_ROOT } from "./helpers.ts";

/**
 * Contract between the runner and the bar: tests/fixtures/live_runner_sample.json is a mid-run `<swarm_dir>/live.json`
 * that the REAL scripts/swarm_run.py wrote (regenerated by `SWARM_WRITE_LIVE_FIXTURE=1 python3 -m pytest
 * tests/test_e2e_swarm.py -k fixture`). tests/test_live_contract.py checks it against the schema; this file feeds the same
 * bytes to the bar's live ingestion and renderer.
 */
interface LiveRun {
  run_id: string;
  task_id: string;
  agent: string;
  state: string;
  elapsed_s: number;
  [key: string]: unknown;
}
interface LiveDoc {
  schema: string;
  swarm: Record<string, number | string | null | Record<string, unknown>>;
  runs: LiveRun[];
  [key: string]: unknown;
}

const doc = JSON.parse(readFileSync(join(REPO_ROOT, "tests", "fixtures", "live_runner_sample.json"), "utf8")) as LiveDoc;
const NOW = 5_000;
const ELAPSED_FIELD = 6; // display columns of the elapsed timer in a row (ELAPSED_COLUMNS)
const plain = (model: SwarmBarModel, width: number, now = NOW) => renderSwarmBar(model, width, undefined, now);

function onlyRun(run: LiveRun): LiveDoc {
  return { ...doc, runs: [run], swarm: { ...doc.swarm, max_parallel: 4, effective_parallel: 4 } };
}

/** Line 2 of a bar that holds exactly this one row. */
function rowLine(run: LiveRun, now: number): string {
  const model = createModel();
  expect(ingestLive(model, onlyRun(run), NOW, 0)).toBe(true);
  const lines = plain(model, 200, now);
  expect(lines.length).toBe(2);
  return lines[1];
}

describe("runner live.json sample feeds the bar", () => {
  test("the fixture is a mid-run snapshot with every row kind the bar draws", () => {
    expect(doc.schema).toBe("swarm.live.v1");
    const states = new Set(doc.runs.map((r) => r.state));
    for (const needed of ["running", "queued", "completed", "waiting", "failed"]) expect(states.has(needed)).toBe(true);
    expect(new Set(doc.runs.map((r) => r.agent)).size).toBe(15);
  });

  test("ingestion accepts it and the summary line carries the runner's own counts", () => {
    const model = createModel();
    expect(ingestLive(model, doc, NOW, 0)).toBe(true);
    const lines = plain(model, 200);
    expect(lines.length).toBeLessThanOrEqual(2);
    const swarm = doc.swarm as Record<string, number>;
    const summary = lines[0];
    expect(summary).toContain("swarm");
    expect(summary).toContain(`${swarm.running} run`);
    expect(summary).toContain(`${swarm.queued} queued`);
    expect(summary).toContain(`${swarm.completed} done`);
    expect(summary).toContain(`${swarm.failed} fail`);
    expect(summary).toContain(`slots ${swarm.running}/${swarm.effective_parallel}`);
    expect(statusText(model, NOW)).toContain(`${swarm.running} run`);
  });

  test("every row is either drawn or counted in '+N more'", () => {
    const model = createModel();
    ingestLive(model, doc, NOW, 0);
    const frame = renderSwarmBarFrame(model, 200, undefined, NOW);
    expect(frame.shown + frame.hidden).toBe(doc.runs.length);
    expect(frame.lines[1]).toContain(`+${frame.hidden} more`);
    // the worst states come first: the failed run is drawn before anything running
    const order = visibleRuns(model, NOW).map((r) => r.state);
    expect(order[0]).toBe("failed");
  });

  test("each of the 15 agents is named with a fixed-width elapsed timer, in every state", () => {
    const agents = new Set<string>();
    for (const run of doc.runs) {
      const line = rowLine(run, NOW);
      const found = new RegExp(`${run.agent} ( *\\d+(?:s|m\\d{2}s|h\\d{2}m))(?: |$)`).exec(line);
      expect(found, `${run.agent} ${run.state}: ${line}`).not.toBeNull();
      expect(found![1].length).toBe(ELAPSED_FIELD);
      expect(found![1].trim()).toBe(formatElapsed(run.elapsed_s));
      agents.add(run.agent);
    }
    expect(agents.size).toBe(15);
  });

  test("state words and glyphs follow the runner's states (never color alone)", () => {
    const words: Record<string, RegExp> = {
      failed: /✕ FAIL /,
      waiting: /◌ wait /,
      queued: /○ queued /,
      completed: /✓ /,
    };
    for (const run of doc.runs) {
      const pattern = words[run.state];
      if (pattern) expect(rowLine(run, NOW)).toMatch(pattern);
    }
    const running = doc.runs.find((r) => r.state === "running")!;
    expect(rowLine(running, NOW)).toContain(running.agent);
  });

  test("a live row's timer keeps counting on the consumer's own clock; a settled row's does not", () => {
    const running = doc.runs.find((r) => r.state === "running")!;
    const done = doc.runs.find((r) => r.state === "completed")!;
    expect(rowLine(running, NOW + 30_000)).toContain(formatElapsed(running.elapsed_s + 30).padStart(ELAPSED_FIELD));
    // a settled row lingers 20 s after it ended and is frozen meanwhile
    expect(rowLine(done, NOW + 5_000)).toContain(formatElapsed(done.elapsed_s).padStart(ELAPSED_FIELD));
  });

  test("a narrow width still prints one summary line and names the worst row without breaking", () => {
    const model = createModel();
    ingestLive(model, doc, NOW, 0);
    for (const width of [120, 80, 60, 40]) {
      const lines = plain(model, width);
      expect(lines.length).toBeLessThanOrEqual(2);
      for (const line of lines) expect(line.length).toBeLessThanOrEqual(width);
    }
    expect(plain(model, 80)[1]).toContain("a14-maintenance");
  });
});
